<script setup>
import { ref, reactive } from 'vue'
const tab = ref('general'), feedback = ref(''), error = ref('')
const form = reactive({ name: 'Axion workspace', hostname: 'panel.example.com', timezone: 'UTC', email: 'admin@example.com', timeout: '30 minutes' })
const toggles = reactive({ digest: true, certificates: true, failures: true, signins: false, restrict: true })
const sessions = ref([{ id: 1, device: 'Firefox · Linux', address: '192.0.2.10', seen: 'Now · example', current: true }, { id: 2, device: 'Safari · macOS', address: '198.51.100.24', seen: '2 hours ago · example', current: false }, { id: 3, device: 'Chrome · Windows', address: '203.0.113.8', seen: 'Yesterday · example', current: false }])
const mfa = ref({ status: 'Not configured · simulated', open: false, enabled: false })
const mfaCode = ref('')
function save() { if (!form.name.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) { error.value = 'Provide a workspace name and a valid example email.'; return }; error.value = ''; feedback.value = 'Preview only — ' + tab.value + ' preferences applied to this design. Nothing was persisted.' }
function setupMfa() { mfa.value.open = true; mfa.value.status = 'Setup in progress · simulated'; error.value = '' }
function confirmMfa() { if (mfaCode.value !== '123456') { error.value = 'Use the public simulated code 123456.'; return }; mfa.value = { status: 'Enabled · simulated', open: false, enabled: true }; mfaCode.value = ''; error.value = ''; feedback.value = 'Preview only — simulated MFA enabled. No real secret was generated.' }
function revokeSession(session) { if (session.current) { feedback.value = 'Preview only — the current example session cannot be revoked here.'; return }; sessions.value = sessions.value.filter(s => s.id !== session.id); feedback.value = 'Preview only — example session removed from this list. No real session was revoked.' }
</script>
<template>
  <main class="w-full pt-16 min-h-screen" style="background: rgb(var(--c-surface))">
    <section><header class="page-heading"><div><p class="ax-label">Workspace / configuration preview</p><h1>Settings</h1><p class="ax-sub">Review general preferences, account security, and notification policies.</p></div><span class="ax-pill ax-pill-info">Preview only · settings are not saved</span></header><p v-if="feedback" class="notice ax-pill ax-pill-info" role="status">{{ feedback }}</p>
      <div class="settings-layout"><nav class="settings-nav" aria-label="Settings categories" role="tablist"><button v-for="item in [{ id: 'general', icon: 'tune', label: 'General' }, { id: 'security', icon: 'shield', label: 'Security' }, { id: 'notifications', icon: 'notifications', label: 'Notifications' }]" :key="item.id" :class="{ active: tab === item.id }" role="tab" :aria-selected="tab === item.id" @click="tab = item.id; error = ''"><span aria-hidden="true" class="material-symbols-outlined">{{ item.icon }}</span>{{ item.label }}</button><p class="ax-sub">Example workspace<br><span class="ax-mono">panel.example.com</span></p></nav>
        <div class="settings-main"><form @submit.prevent="save"><section v-if="tab === 'general'" class="ax-card ax-card-pad"><p class="ax-label">Workspace identity</p><h2 class="ax-title">General preferences</h2><p class="ax-sub">These example values describe the panel, not a live server.</p><div class="form-grid fields"><div class="ax-field"><label for="settings-name" class="ax-label">Workspace name</label><input id="settings-name" v-model="form.name" class="ax-input" required></div><div class="ax-field"><label for="settings-host" class="ax-label">Example panel hostname</label><input id="settings-host" v-model="form.hostname" class="ax-input" required></div><div class="ax-field"><label for="settings-zone" class="ax-label">Display timezone</label><select id="settings-zone" v-model="form.timezone" class="ax-select"><option>UTC</option><option>Asia/Jakarta</option><option>Europe/London</option><option>America/New_York</option></select></div><div class="ax-field"><label for="settings-email" class="ax-label">Example contact email</label><input id="settings-email" v-model="form.email" type="email" class="ax-input" required></div></div><div class="ax-divider"></div><p class="ax-label">Environment</p><dl class="environment"><div><dt>Configuration source</dt><dd>In-memory design example</dd></div><div><dt>Persistence</dt><dd>Disabled · reload resets all changes</dd></div></dl></section>
          <template v-if="tab === 'security'"><section class="ax-card ax-card-pad"><div class="ax-hd"><div><p class="ax-label">Account protection / simulated</p><h2 class="ax-title">Multi-factor authentication</h2></div><span class="ax-pill" :class="mfa.enabled ? 'ax-pill-ok' : 'ax-pill-warn'">{{ mfa.status }}</span></div><p class="ax-sub">Preview the setup flow. No authenticator enrollment, secret, or recovery code is created.</p><button type="button" class="ax-btn ax-btn-ghost" @click="setupMfa">{{ mfa.enabled ? 'Review' : 'Set up' }} simulated MFA · Preview only</button><div v-if="mfa.open" class="mfa-preview"><p class="ax-label">Simulated enrollment / no QR code</p><p class="ax-sub">A real setup would display a QR code here. For this preview, enter <strong class="ax-mono">123456</strong>.</p><label for="mfa-code" class="ax-label">Example confirmation code</label><div class="mfa-entry"><input id="mfa-code" v-model="mfaCode" class="ax-input" inputmode="numeric" maxlength="6" autocomplete="off" placeholder="123456"><button type="button" class="ax-btn ax-btn-primary" @click="confirmMfa">Confirm · Preview only</button><button type="button" class="ax-btn ax-btn-ghost" @click="mfa.open = false; mfaCode = ''; error = ''">Cancel</button></div></div><div class="ax-divider"></div><div class="setting-row"><div><strong>Restrict panel access</strong><p class="ax-sub">Simulated trusted-network policy; no firewall rules are applied.</p></div><button type="button" class="ax-toggle" :class="{ on: toggles.restrict }" role="switch" :aria-checked="toggles.restrict" aria-label="Trusted network restriction preview" @click="toggles.restrict = !toggles.restrict"></button></div><div class="ax-field timeout"><label for="session-timeout" class="ax-label">Idle timeout (example)</label><select id="session-timeout" v-model="form.timeout" class="ax-select"><option>15 minutes</option><option>30 minutes</option><option>1 hour</option></select></div></section>
          <section class="ax-card sessions"><div class="ax-card-pad"><h2 class="ax-title">Example sessions</h2><p class="ax-sub">Documentation IP addresses, not real activity. Revocation is simulated.</p></div><div class="table-scroll"><table class="ax-table"><thead><tr><th>Device</th><th>Address</th><th>Last seen</th><th></th></tr></thead><tbody><tr v-for="session in sessions" :key="session.id"><td>{{ session.device }} <span v-if="session.current" class="ax-pill ax-pill-info">Current example</span></td><td class="ax-mono">{{ session.address }}</td><td class="ax-mono">{{ session.seen }}</td><td><button v-if="!session.current" type="button" class="ax-btn ax-btn-danger" @click="revokeSession(session)">Revoke · Preview only</button><span v-else class="ax-sub">This preview</span></td></tr></tbody></table></div></section></template>
          <section v-if="tab === 'notifications'" class="ax-card ax-card-pad"><p class="ax-label">Delivery preferences</p><h2 class="ax-title">Notifications</h2><p class="ax-sub">Example alert rules only. No email, webhook, or external message is sent.</p><div v-for="item in [{ key: 'certificates', name: 'Certificate expiration', description: 'Example warnings at 14, 7, and 3 days before expiration.' }, { key: 'failures', name: 'Job failures', description: 'Example notification when a scheduled task exits with an error.' }, { key: 'signins', name: 'New sign-in activity', description: 'Example alert for an unfamiliar device or location.' }, { key: 'digest', name: 'Daily summary', description: 'One illustrative digest each morning at 08:00 UTC.' }]" :key="item.key" class="setting-row"><div><strong>{{ item.name }}</strong><p class="ax-sub">{{ item.description }}</p></div><button type="button" class="ax-toggle" :class="{ on: toggles[item.key] }" role="switch" :aria-checked="toggles[item.key]" :aria-label="item.name + ' preview'" @click="toggles[item.key] = !toggles[item.key]"></button></div><div class="ax-divider"></div><span class="ax-pill ax-pill-dim">Delivery channel · example email</span><p class="ax-sub ax-mono">{{ form.email }}</p></section>
          <p v-if="error" role="alert" class="error">{{ error }}</p><footer class="panel-footer save-footer"><span class="ax-sub">Changes last only for this page instance.</span><button class="ax-btn ax-btn-primary">Save {{ tab }} · Preview only</button></footer>
        </form></div>
      </div>
    </section>
  </main>
</template>
<style scoped>
.settings-layout{display:grid;grid-template-columns:210px minmax(0,1fr);gap:28px;max-width:1180px}.settings-nav{display:flex;flex-direction:column;gap:6px}.settings-nav button{display:flex;align-items:center;gap:12px;padding:14px 16px;border:0;border-radius:6px;background:none;color:rgb(var(--c-on-surface-variant));font:600 13px 'Plus Jakarta Sans',sans-serif;text-align:left;cursor:pointer}.settings-nav .active{color:rgb(var(--c-primary));background:rgb(var(--c-primary)/.1)}.settings-nav button span{font-size:20px}.settings-nav>p{padding:16px;line-height:23px}.fields{margin-top:28px}.environment{margin:18px 0 0;font-size:12px}.environment>div{display:flex;justify-content:space-between;gap:20px;padding:12px 0}.environment dt{color:rgb(var(--c-outline))}.environment dd{margin:0;font-family:'JetBrains Mono',monospace}.setting-row{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;border-bottom:1px solid rgb(var(--c-outline-variant)/.2)}.setting-row strong{font-size:13px}.setting-row p{margin:6px 0 0}.timeout{max-width:300px;margin-top:22px}.sessions{margin-top:20px;overflow:hidden}.mfa-preview{margin:20px 0;padding:16px;background:rgb(var(--c-surface-container));border-radius:6px}.mfa-entry{display:flex;gap:8px;margin-top:8px;flex-wrap:wrap}.mfa-entry input{width:140px}.notice{white-space:normal;margin-bottom:16px}.error{color:rgb(var(--c-error));font-size:12px}.save-footer{margin-top:20px}.settings-main .ax-title{margin:8px 0 10px}@media(max-width:800px){.settings-layout{grid-template-columns:1fr;gap:20px}.settings-nav{flex-direction:row;overflow:auto}.settings-nav>p{display:none}.settings-nav button{white-space:nowrap}.environment>div{flex-wrap:wrap}.ax-hd{flex-wrap:wrap}}button:focus-visible{outline:2px solid rgb(var(--c-primary));outline-offset:3px}
</style>
